// Refresh scores only from the prepared class packets. No Google or grading requests.
import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{createRequire}from'node:module';import{fileURLToPath}from'node:url';import{buildAcademicLeaderboard}from'./academic-score.mjs';import{sealForClass,isSealed}from'./sealed.mjs';
// Classes whose edge Worker requires ?t=<token> (IELTS_TOKEN_GUARD_V2); others must keep plain URLs.
const tokenGuarded=new Set([45,46,47,48,49,50,51,52]),tokenByHash=new Map((JSON.parse(process.env.IELTS_UI_PARENT_ROSTER||'[]')||[]).map(p=>[p.hash,p.token])),require=createRequire(import.meta.url),folder=path.dirname(fileURLToPath(import.meta.url)),resolver=require('./ielts-assignment-resolver.cjs'),config=JSON.parse(fs.readFileSync(folder+'/classes.json')).classes;
for(const c of config){const source=fs.readFileSync(path.resolve(c.route+'/index.html'),'utf8'),match=source.match(/\{"baseUrl":"https:\/\/[^\"]+\/data\/","hashes":\[[^\]]+\]\}/);if(!match)throw Error('PREPARED_CONFIG_MISSING');const transport=JSON.parse(match[0]);if(transport.baseUrl!==c.baseUrl)throw Error('CLASS_TRANSPORT_MISMATCH');
 const packets=[];let cursor=0,revoked=0;async function capture(){while(cursor<transport.hashes.length){const hash=transport.hashes[cursor++],r=await fetch(c.baseUrl+hash+'.json'+(tokenGuarded.has(c.number)&&tokenByHash.has(hash)?'?t='+encodeURIComponent(tokenByHash.get(hash)):''),{signal:AbortSignal.timeout(30000)});if(r.status===410){revoked++;continue;}if(!r.ok)throw Error('CLASS_'+c.number+'_PREPARED_HTTP_'+r.status);const packet=await r.json();if(packet.className!==c.className||packet.actions.profile?.student?.name!==packet.name)throw Error('PREPARED_IDENTITY');packets.push({hash,packet});}}
 try{await Promise.all([capture(),capture(),capture()]);packets.sort((a,b)=>a.hash.localeCompare(b.hash));const result=buildAcademicLeaderboard(packets,{now:Date.now(),resolveAssignment:item=>resolver.resolve(item),commonHabitScope:true});result.sourceCoverage={active:transport.hashes.length-revoked,ready:packets.length,unavailable:0};result.entries=result.entries.map(e=>({name:e.name,hash:e.hash,rank:e.rank,total:e.total,provisional:e.provisional,missing:e.missing,coverage:e.coverage,components:Object.fromEntries(Object.entries(e.components).map(([k,v])=>[k,{value:v.value,band:v.band,sourceDate:v.sourceDate,title:v.title,coverage:v.coverage,completionRate:v.completionRate,onTimeRate:v.onTimeRate}]))}));result.sourceFingerprint=createHash('sha256').update(JSON.stringify({scope:result.scope,entries:result.entries,day:new Date(Date.now()+7*3600000).toISOString().slice(0,10)})).digest('hex');const out=path.resolve(c.route+'/data/academic-leaderboard.json');let old;try{old=JSON.parse(fs.readFileSync(out));}catch(_){}if(old?.sourceFingerprint!==result.sourceFingerprint||!isSealed(old)){const tokens=transport.hashes.map(h=>tokenByHash.get(h)).filter(Boolean);if(!tokens.length)throw Error('ROSTER_TOKENS_REQUIRED');fs.writeFileSync(out,JSON.stringify(sealForClass(tokens,JSON.stringify(result),{sourceFingerprint:result.sourceFingerprint})));}console.log(JSON.stringify({class:c.number,pupils:packets.length,ok:true}));}catch(e){console.log(JSON.stringify({class:c.number,keptPrevious:true,error:e.message}));}}
